    "guide.step1.hint": "Nenda kwenye Matawi ili kusanidi maeneo na keshia.",
    "guide.step2.title": "2. Weka Vitengo & Bidhaa",
    "guide.step2.desc": "Unda vitengo na uweke bidhaa zenye bei za kuuza, gharama na misimbo pau.",
    "guide.step2.hint": "Fungua Bidhaa ili kuunda orodha yako ya bidhaa.",
    "guide.step3.title": "3. Usimamizi wa Stoki & Bidhaa",
    "guide.step3.desc": "Weka idadi ya mwanzo ya stoki, pokea maagizo kutoka kwa wauzaji, na fuatilia tahadhari za stoki.",
    "guide.step3.hint": "Fungua Stoki kurekebisha idadi na kufuatilia mienendo.",
    "guide.step4.title": "4. Fungua Keshia (Usimamizi wa Pesa)",
    "guide.step4.desc": "Kabla ya kuanza kuuza, fungua zamu ya keshia ukiweka kiwango cha mwanzo cha fedha taslimu.",
    "guide.step4.hint": "Fungua Keshia kuweka fedha za kuanzia na kusimamia fedha taslimu.",
    "guide.step5.title": "5. Fanya Mauzo na Upokee Malipo",
    "guide.step5.desc": "Uza bidhaa haraka kupitia POS ya kugusa, Maagizo ya meza au kichanganuzi cha msimbo pau.",
    "guide.step5.hint": "Nenda kwenye POS kuweka bidhaa, kuchagua njia ya malipo na kutoa risiti.",
    "guide.step6.title": "6. Sajili Wateja & Pointi za Uaminifu",
    "guide.step6.desc": "Hifadhi taarifa za wateja, fuatilia historia ya ununuzi na ongeza pointi za uaminifu.",
    "guide.step6.hint": "Fungua Wateja kuunda wasifu na kusimamia mikopo/pointi.",
    "guide.step7.title": "7. Funga Zamu & Ripoti za Ukaguzi",
    "guide.step7.desc": "Hesabu fedha taslimu, linganisha na mauzo ya mfumo, funga keshia na kagua ripoti za mauzo.",
    "guide.step7.hint": "Nenda kwenye Keshia kufunga zamu na Ripoti kuona takwimu za mauzo.",
